    "code": "import React from \"react\";\n\nexport function UserTestimonials() {\n  return (\n    <div className=\"py-5 dark:bg-gray-900\">\r\n    <div className=\"container flex flex-col items-center justify-center w-full p-6 mx-auto text-center xl:px-0\">\r\n        <div className=\"text-sm font-bold tracking-wider text-indigo-600 uppercase\">Testimonials</div>\r\n        <h2 className=\"max-w-2xl mt-3 text-3xl font-bold leading-snug tracking-tight text-gray-800 lg:leading-tight lg:text-4xl dark:text-white\">Here's what our customers said</h2>\r\n        <p className=\"max-w-2xl py-4 text-lg leading-normal text-gray-500 lg:text-xl xl:text-xl dark:text-gray-300\">Testimonials is a great way to increase brand trust and awareness. Use this section to highlight your popular customers.</p>\r\n    </div>\r\n    <div className=\"container p-6 mx-auto mb-10 xl:px-0\">\r\n        <div className=\"grid gap-10 lg:grid-cols-2 xl:grid-cols-3\">\r\n            <div className=\"lg:col-span-2 xl:col-auto\">\r\n                <div className=\"flex flex-col justify-between w-full h-full px-6 py-6 bg-gray-100 dark:bg-gray-800 md:px-14 rounded-2xl md:py-14 dark:bg-trueGray-800\">\r\n                    <p className=\"text-2xl leading-normal dark:text-gray-300\">Share a <mark className=\"mx-1 text-indigo-800 bg-indigo-100 rounded-md ring-indigo-100 ring-4 dark:ring-indigo-900 dark:bg-indigo-900 dark:text-indigo-200\">testimonial</mark> that hits some of your benefits from one of your popular customers.</p>\r\n                    <div className=\"flex items-center mt-8 space-x-3\">\r\n                        <div className=\"flex-shrink-0 overflow-hidden rounded-full w-14 h-14\">\r\n                            <img alt=\"Avatar\" src=\"https://images.unsplash.com/photo-1511485977113-f34c92461ad9?crop=faces&cs=tinysrgb&fit=crop&fm=jpg&ixid=MnwxfDB8MXxhbGx8fHx8fHx8fHwxNjIwMTQ5ODEx&ixlib=rb-1.2.1&q=80&w=100&h=100\" loading=\"lazy\" />\r\n                        </div>\r\n                        <div>\r\n                            <div className=\"text-lg font-medium text-gray-200\">Sarah Steiner</div>\r\n                            <div className=\"text-gray-600 dark:text-gray-400\">VP Sales at Google</div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div className=\"\">\r\n                <div className=\"flex flex-col justify-between w-full h-full px-6 py-6 bg-gray-100 dark:bg-gray-800 md:px-14 rounded-2xl md:py-14 dark:bg-trueGray-800\">\r\n                    <p className=\"text-2xl leading-normal dark:text-gray-300\">Make sure you only pick the <mark className=\"mx-1 text-indigo-800 bg-indigo-100 rounded-md ring-indigo-100 ring-4 dark:ring-indigo-900 dark:bg-indigo-900 dark:text-indigo-200\">right sentence</mark> to keep it short and simple.</p>\r\n                    <div className=\"flex items-center mt-8 space-x-3\">\r\n                        <div className=\"flex-shrink-0 overflow-hidden rounded-full w-14 h-14\">\r\n                            <img alt=\"Avatar\" src=\"https://images.unsplash.com/photo-1463453091185-61582044d556?ixlib=rb-1.2.1&ixid=MnwxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8&auto=format&crop=faces&fit=crop&w=100&h=100&q=80\" loading=\"lazy\" />\r\n                        </div>\r\n                        <div>\r\n                            <div className=\"text-lg font-medium text-gray-200\">Dylan Ambrose</div>\r\n                            <div className=\"text-gray-600 dark:text-gray-400\">Lead marketer at Netflix </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n            <div className=\"\">\r\n                <div className=\"flex flex-col justify-between w-full h-full px-6 py-6 bg-gray-100 dark:bg-gray-800 md:px-14 rounded-2xl md:py-14 dark:bg-trueGray-800\">\r\n                    <p className=\"text-2xl leading-normal dark:text-gray-300\">This is an <mark className=\"mx-1 text-indigo-800 bg-indigo-100 rounded-md ring-indigo-100 ring-4 dark:ring-indigo-900 dark:bg-indigo-900 dark:text-indigo-200\">awesome</mark> landing page template I've seen. I would use this for anything.</p>\r\n                    <div className=\"flex items-center mt-8 space-x-3\">\r\n                        <div className=\"flex-shrink-0 overflow-hidden rounded-full w-14 h-14\">\r\n                            <img alt=\"Avatar\" src=\"https://images.unsplash.com/photo-1624224971170-2f84fed5eb5e?ixlib=rb-1.2.1&ixid=MnwxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8&auto=format&fit=crop&w=100&h=100&crop=faces&q=80\" loading=\"lazy\" />\r\n                        </div>\r\n                        <div>\r\n                            <div className=\"text-lg font-medium text-gray-200\">Gabrielle Winn</div>\r\n                            <div className=\"text-gray-600 dark:text-gray-400\">Co-founder of Acme Inc</div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\n</div>\n  );\n}"
